1	#include "mla_combine.h"
2	
3	#include <cute/tensor.hpp>
4	#include <cutlass/cutlass.h>
5	#include <cutlass/array.h>
6	#include <cutlass/numeric_types.h>
7	
8	#include "params.h"
9	#include "utils.h"
10	#include "config.h"  // for BLOCK_SIZE_M and HEAD_DIM_V
11	
12	using namespace cute;
13	
14	template<typename ElementT, int HEAD_DIM_V, int BLOCK_SIZE_M, int MAX_SPLITS, int NUM_THREADS>
15	__global__ void __launch_bounds__(NUM_THREADS)
16	flash_fwd_mla_combine_kernel(__grid_constant__ const Flash_fwd_mla_params params) {
17	    // grid_shape: [batch_size, num_q_heads*s_q / BLOCK_SIZE_M]
18	    // Each CTA gathers the activation of some heads from one batch, do scaling & accumulation, and save the result
19	    static_assert(NUM_THREADS/32 == BLOCK_SIZE_M); // The number of warps == block_size_m
20	    const int batch_idx = blockIdx.x;
21	    const int m_block_idx = blockIdx.y;
22	    const int warp_idx = threadIdx.x / 32;
23	    const int lane_idx = threadIdx.x % 32;
24	
25	    const int start_split_idx = __ldg(params.num_splits_ptr + batch_idx);
26	    const int end_split_idx = __ldg(params.num_splits_ptr + batch_idx + 1);
27	    const int my_num_splits = end_split_idx - start_split_idx;
28	    FLASH_DEVICE_ASSERT(my_num_splits <= MAX_SPLITS);
29	    if (my_num_splits == 1) {
30	        return;
31	    }
32	    
33	    const int num_q_seqs = params.q_seq_per_hk * params.h_k;
34	    const int num_cur_valid_q_seqs = min(BLOCK_SIZE_M, num_q_seqs - m_block_idx*BLOCK_SIZE_M);
35	    Tensor gLseAccum = make_tensor(
36	        make_gmem_ptr((float*)params.softmax_lseaccum_ptr + start_split_idx*num_q_seqs + m_block_idx*BLOCK_SIZE_M),
37	        Shape<Int<MAX_SPLITS>, Int<BLOCK_SIZE_M>>{},
38	        make_stride(num_q_seqs, _1{})
39	    );
40	    Tensor gLse = make_tensor(
41	        make_gmem_ptr((float*)params.softmax_lse_ptr + batch_idx*num_q_seqs + m_block_idx*BLOCK_SIZE_M),
42	        Shape<Int<BLOCK_SIZE_M>>{},
43	        Stride<_1>{}
44	    );
45	    
46	    extern __shared__ float smem_buf[];
47	    Tensor sLseScale = make_tensor(
48	        make_smem_ptr(smem_buf),
49	        Shape<Int<BLOCK_SIZE_M>, Int<MAX_SPLITS>>{},
50	        Stride<Int<MAX_SPLITS+1>, _1>{} // +1 to avoid bank conflict
51	    );
52	    
53	    // Wait for the previous kernel (the MLA kernel) to finish
54	    cudaGridDependencySynchronize();
55	    
56	    // Read gLseAccum into sLseScale
57	    {
58	        #pragma unroll 4
59	        for (int elem_idx = threadIdx.x; elem_idx < my_num_splits*BLOCK_SIZE_M; elem_idx += NUM_THREADS) {
60	            int split_idx = elem_idx / BLOCK_SIZE_M;
61	            int seq_idx = elem_idx % BLOCK_SIZE_M;
62	            sLseScale(seq_idx, split_idx) = seq_idx < num_cur_valid_q_seqs ? gLseAccum(split_idx, seq_idx) : -INFINITY;
63	        }
64	        __syncthreads();
65	    }
66	
67	    if (warp_idx >= num_cur_valid_q_seqs)
68	        return;
69	
70	    // Warp #i gathers LseAccum for seq #i
71	    {
72	        constexpr int NUM_LSE_PER_THREAD = cute::ceil_div(MAX_SPLITS, 32);
73	        float local_lse[NUM_LSE_PER_THREAD];
74	        CUTLASS_PRAGMA_UNROLL
75	        for (int i = 0; i < NUM_LSE_PER_THREAD; ++i) {
76	            const int split_idx = i*32 + lane_idx;
77	            local_lse[i] = split_idx < my_num_splits ? sLseScale(warp_idx, split_idx) : -INFINITY;
78	        }
79	
80	        float max_lse = -INFINITY;
81	        CUTLASS_PRAGMA_UNROLL
82	        for (int i = 0; i < NUM_LSE_PER_THREAD; ++i)
83	            max_lse = max(max_lse, local_lse[i]);
84	        CUTLASS_PRAGMA_UNROLL
85	        for (int offset = 16; offset >= 1; offset /= 2)
86	            max_lse = max(max_lse, __shfl_xor_sync(uint32_t(-1), max_lse, offset));
87	        max_lse = max_lse == -INFINITY ? 0.0f : max_lse;  // In case all local LSEs are -inf
88	
89	        float sum_lse = 0;
90	        CUTLASS_PRAGMA_UNROLL
91	        for (int i = 0; i < NUM_LSE_PER_THREAD; ++i)
92	            sum_lse = sum_lse + exp2f(local_lse[i] - max_lse);
93	        CUTLASS_PRAGMA_UNROLL
94	        for (int offset = 16; offset >= 1; offset /= 2)
95	            sum_lse = sum_lse + __shfl_xor_sync(uint32_t(-1), sum_lse, offset);
96	
97	        float global_lse = (sum_lse == 0.f || sum_lse != sum_lse) ? INFINITY : log2f(sum_lse) + max_lse;
98	        if (lane_idx == 0)
99	            gLse(warp_idx) = global_lse / (float)M_LOG2E;
100	
101	        CUTLASS_PRAGMA_UNROLL
102	        for (int i = 0; i < NUM_LSE_PER_THREAD; ++i) {
103	            const int split_idx = i*32 + lane_idx;
104	            if (split_idx < my_num_splits) sLseScale(warp_idx, split_idx) = exp2f(local_lse[i] - global_lse);
105	        }
106	    }
107	
108	    __syncwarp();
109	
110	    // Warp #i accumulates activation for seq #i
111	    {
112	        const int64_t row_offset_oaccum = (int64_t)(start_split_idx*num_q_seqs+m_block_idx*BLOCK_SIZE_M+warp_idx) * HEAD_DIM_V;
113	        Tensor gOaccum = make_tensor(
114	            make_gmem_ptr(reinterpret_cast<float *>(params.oaccum_ptr) + row_offset_oaccum),
115	            Shape<Int<MAX_SPLITS>, Int<HEAD_DIM_V>>{},
116	            make_stride(num_q_seqs*HEAD_DIM_V, _1{})
117	        );
118	
119	        static_assert(HEAD_DIM_V % 32 == 0);
120	        constexpr int ELEMS_PER_THREAD = HEAD_DIM_V / 32;
121	        float result[ELEMS_PER_THREAD];
122	        CUTLASS_PRAGMA_UNROLL
123	        for (int i = 0; i < ELEMS_PER_THREAD; ++i)
124	            result[i] = 0.0f;
125	
126	        #pragma unroll 2
127	        for (int split = 0; split < my_num_splits; ++split) {
128	            float lse_scale = sLseScale(warp_idx, split);
129	            if (lse_scale != 0.f) {
130	                CUTLASS_PRAGMA_UNROLL
131	                for (int i = 0; i < ELEMS_PER_THREAD; ++i) {
132	                    result[i] += lse_scale * gOaccum(split, lane_idx + i*32);
133	                }
134	            }
135	        }
136	
137	        cudaTriggerProgrammaticLaunchCompletion();
138	        
139	        const int q_seq_idx = m_block_idx*BLOCK_SIZE_M + warp_idx;
140	        const int k_head_idx = q_seq_idx / params.q_seq_per_hk;
141	        auto o_ptr = reinterpret_cast<ElementT *>(params.o_ptr) + batch_idx*params.o_batch_stride + k_head_idx*params.o_head_stride + (q_seq_idx%params.q_seq_per_hk)*params.o_row_stride;
142	        Tensor gO = make_tensor(
143	            make_gmem_ptr(o_ptr),
144	            Shape<Int<HEAD_DIM_V>>{},
145	            Stride<_1>{}
146	        );
147	
148	        CUTLASS_PRAGMA_UNROLL
149	        for (int i = 0; i < ELEMS_PER_THREAD; ++i)
150	            gO(lane_idx+i*32) = (ElementT)result[i];
151	    }
152	}
153	
