155	#define MLA_NUM_SPLITS_SWITCH(NUM_SPLITS, NAME, ...)       \
156	    [&] {                                                  \
157	        if (NUM_SPLITS <= 32) {                            \
158	            constexpr static int NAME = 32;                \
159	            return __VA_ARGS__();                          \
160	        } else if (NUM_SPLITS <= 64) {                     \
161	            constexpr static int NAME = 64;                \
162	            return __VA_ARGS__();                          \
163	        } else if (NUM_SPLITS <= 96) {                     \
164	            constexpr static int NAME = 96;                \
165	            return __VA_ARGS__();                          \
166	        } else if (NUM_SPLITS <= 128) {                    \
167	            constexpr static int NAME = 128;               \
168	            return __VA_ARGS__();                          \
169	        } else if (NUM_SPLITS <= 160) {                    \
170	            constexpr static int NAME = 160;               \
171	            return __VA_ARGS__();                          \
172	        } else {                                           \
173	            FLASH_ASSERT(false);                           \
174	        }                                                  \
175	    }()
176	
177	
178	template<typename ElementT>
179	void run_flash_mla_combine_kernel(Flash_fwd_mla_params &params, cudaStream_t stream) {
180	    MLA_NUM_SPLITS_SWITCH(params.num_sm_parts, NUM_SPLITS, [&] {
181	        constexpr int BLOCK_SIZE_M = 8;
182	        constexpr int NUM_THREADS = BLOCK_SIZE_M*32;
183	        constexpr size_t smem_size = BLOCK_SIZE_M*(NUM_SPLITS+1)*sizeof(float);
184	        auto combine_kernel = &flash_fwd_mla_combine_kernel<ElementT, Config::HEAD_DIM_V, BLOCK_SIZE_M, NUM_SPLITS, NUM_THREADS>;
185	        // printf("Running flash_fwd_mla_combine_kernel with %d splits\n", NUM_SPLITS);
186	        // printf("smem_size: %zu\n", smem_size);
187	        CHECK_CUDA(cudaFuncSetAttribute(combine_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size));
188	        // Use cudaLaunchKernelEx to enable PDL (Programmatic Dependent Launch)
189	        cudaLaunchAttribute attribute[1];
190	        attribute[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;
191	        attribute[0].val.programmaticStreamSerializationAllowed = 1;
192	        cudaLaunchConfig_t combine_kernel_config = {
193	            dim3(params.b, cute::ceil_div(params.h_k*params.q_seq_per_hk, BLOCK_SIZE_M), 1),
194	            dim3(NUM_THREADS, 1, 1),
195	            smem_size,
196	            stream,
197	            attribute,
198	            1
199	        };
200	        cudaLaunchKernelEx(&combine_kernel_config, combine_kernel, params);
201	    });
202	    CHECK_CUDA_KERNEL_LAUNCH();
203	}
204	
205	template void run_flash_mla_combine_kernel<cutlass::bfloat16_t>(Flash_fwd_mla_params &params, cudaStream_t stream);
206	
207	#ifndef FLASH_MLA_DISABLE_FP16
208	template void run_flash_mla_combine_kernel<cutlass::half_t>(Flash_fwd_mla_params &params, cudaStream_t stream);
209	#endif

