19	#define CHECK_DEVICE(x) TORCH_CHECK(x.is_cuda(), #x " must be on CUDA")
20	#define CHECK_SHAPE(x, ...) TORCH_CHECK(x.sizes() == torch::IntArrayRef({__VA_ARGS__}), #x " must have shape (" #__VA_ARGS__ ")")
21	#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
22	
23	std::vector<at::Tensor>
24	get_mla_metadata(
25	    at::Tensor &seqlens_k,
26	    const int num_heads_per_head_k,
27	    const int num_heads_k
28	) {
29	    CHECK_DEVICE(seqlens_k);
30	    TORCH_CHECK(seqlens_k.is_contiguous());
31	    TORCH_CHECK(seqlens_k.dtype() == torch::kInt32);
32	
33	    int batch_size = seqlens_k.size(0);
34	    int *seqlens_k_ptr = seqlens_k.data_ptr<int>();
35	    auto options = seqlens_k.options();
36	
37	    auto dprops = at::cuda::getCurrentDeviceProperties();
38	    int sm_count = dprops->multiProcessorCount;
39	    int num_sm_parts = sm_count / num_heads_k / cutlass::ceil_div(num_heads_per_head_k, Config::BLOCK_SIZE_M);
40	
41	    auto tile_scheduler_metadata = torch::empty({num_sm_parts, TileSchedulerMetaDataSize}, options);
42	    auto num_splits = torch::empty({batch_size + 1}, options);
43	    int *tile_scheduler_metadata_ptr = tile_scheduler_metadata.data_ptr<int>();
44	    int *num_splits_ptr = num_splits.data_ptr<int>();
45	
46	    at::cuda::CUDAGuard device_guard{(char)seqlens_k.get_device()};
47	    auto stream = at::cuda::getCurrentCUDAStream().stream();
48	    Mla_metadata_params params = {};
49	    params.seqlens_k_ptr = seqlens_k_ptr;
50	    params.tile_scheduler_metadata_ptr = tile_scheduler_metadata_ptr;
51	    params.num_splits_ptr = num_splits_ptr;
52	    params.batch_size = batch_size;
53	    params.block_size_n = Config::PAGE_BLOCK_SIZE;
54	    params.fixed_overhead_num_blocks = Config::FIXED_OVERHEAD_NUM_BLOCKS;
55	    params.num_sm_parts = num_sm_parts;
56	    run_get_mla_metadata_kernel(params, stream);
57	
58	    return {tile_scheduler_metadata, num_splits};
59	}
60	
61	std::vector<at::Tensor>
62	mha_fwd_kvcache_mla(
63	    at::Tensor &q,                               // batch_size x seqlen_q x num_heads x head_size
64	    const at::Tensor &kcache,                    // num_blocks x page_block_size x num_heads_k x head_size
65	    const int head_size_v,
66	    const at::Tensor &seqlens_k,                 // batch_size
67	    const at::Tensor &block_table,               // batch_size x max_num_blocks_per_seq
68	    const float softmax_scale,
69	    bool is_causal,
70	    const at::Tensor &tile_scheduler_metadata,   // num_sm_parts x TileSchedulerMetaDataSize
71	    const at::Tensor &num_splits                 // batch_size + 1
72	) {
73	    // Check the architecture
74	    auto dprops = at::cuda::getCurrentDeviceProperties();
75	    bool is_sm90 = dprops->major == 9 && dprops->minor == 0;
76	    TORCH_CHECK(is_sm90);
77	
78	    // Check data types
79	    auto q_dtype = q.dtype();
80	    TORCH_CHECK(q_dtype == torch::kBFloat16 || q_dtype == torch::kHalf);
81	    TORCH_CHECK(kcache.dtype() == q_dtype, "query and key must have the same dtype");
82	    TORCH_CHECK(seqlens_k.dtype() == torch::kInt32, "seqlens_k must have dtype int32");
83	    TORCH_CHECK(block_table.dtype() == torch::kInt32, "block_table must have dtype torch.int32");
84	    TORCH_CHECK(tile_scheduler_metadata.dtype() == torch::kInt32, "tile_scheduler_metadata must have dtype int32");
85	    TORCH_CHECK(num_splits.dtype() == torch::kInt32, "num_splits must have dtype int32");
86	
87	    // Check device
88	    CHECK_DEVICE(q);
89	    CHECK_DEVICE(kcache);
90	    CHECK_DEVICE(seqlens_k);
91	    CHECK_DEVICE(block_table);
92	    CHECK_DEVICE(tile_scheduler_metadata);
93	    CHECK_DEVICE(num_splits);
94	
95	    // Check layout
96	    TORCH_CHECK(q.stride(-1) == 1, "Input tensor must have contiguous last dimension");
97	    TORCH_CHECK(kcache.stride(-1) == 1, "Input tensor must have contiguous last dimension");
98	    CHECK_CONTIGUOUS(seqlens_k);
99	    TORCH_CHECK(block_table.stride(-1) == 1, "block_table must have contiguous last dimension");
100	    CHECK_CONTIGUOUS(tile_scheduler_metadata);
101	    CHECK_CONTIGUOUS(num_splits);
102	
103	    const auto sizes = q.sizes();
104	    const int batch_size = sizes[0];
105	    const int seqlen_q_ori = sizes[1];
106	    const int num_heads_q = sizes[2];
107	    const int head_size_k = sizes[3];
108	    TORCH_CHECK(head_size_k % 64 == 0, "Only head_size_k must be a multiple of 64");
109	    TORCH_CHECK(head_size_v % 64 == 0, "Only head_size_v must be a multiple of 64");
110	
111	    const int max_num_blocks_per_seq = block_table.size(1);
112	    const int num_blocks = kcache.size(0);
113	    const int page_block_size = kcache.size(1);
114	    const int num_heads_k = kcache.size(2);
115	    TORCH_CHECK(batch_size > 0, "batch size must be postive");
116	    TORCH_CHECK(num_heads_q % num_heads_k == 0, "Number of heads in key/value must divide number of heads in query");
117	
118	    if (seqlen_q_ori == 1) { is_causal = false; }
119	
120	    const int num_q_heads_per_hk = num_heads_q / num_heads_k;
121	    const int q_seq_per_hk = seqlen_q_ori * num_q_heads_per_hk;
122	    const int num_heads = num_heads_k;
123	    q = q.view({batch_size, seqlen_q_ori, num_heads_k, num_q_heads_per_hk, head_size_k}).transpose(2, 3)
124	            .reshape({batch_size, q_seq_per_hk, num_heads, head_size_k});
125	
126	    CHECK_SHAPE(q, batch_size, q_seq_per_hk, num_heads, head_size_k);
127	    CHECK_SHAPE(kcache, num_blocks, page_block_size, num_heads_k, head_size_k);
128	    CHECK_SHAPE(seqlens_k, batch_size);
129	    CHECK_SHAPE(block_table, batch_size, max_num_blocks_per_seq);
130	    TORCH_CHECK(tile_scheduler_metadata.size(1) == TileSchedulerMetaDataSize);
131	    CHECK_SHAPE(num_splits, batch_size+1);
132	
133	    at::cuda::CUDAGuard device_guard{(char)q.get_device()};
134	
135	    auto opts = q.options();
136	    at::Tensor out = torch::empty({batch_size, q_seq_per_hk, num_heads, head_size_v}, opts);
137	    at::Tensor softmax_lse = torch::empty({batch_size, num_heads, q_seq_per_hk}, opts.dtype(at::kFloat));
138	    CHECK_CONTIGUOUS(softmax_lse);
139	
140	    Flash_fwd_mla_params params = {};
141	    // Set the sizes.
142	    params.b = batch_size;
143	    params.s_q = seqlen_q_ori;
144	    params.q_seq_per_hk = q_seq_per_hk;
145	    params.seqlens_k_ptr = seqlens_k.data_ptr<int>();
146	    params.h_q = num_heads_q;
147	    params.h_k = num_heads_k;
148	    params.num_blocks = num_blocks;
149	    params.q_head_per_hk = num_q_heads_per_hk;
150	    params.is_causal = is_causal;
151	    params.d = head_size_k;
152	    params.d_v = head_size_v;
153	    params.scale_softmax = softmax_scale;
154	    params.scale_softmax_log2 = float(softmax_scale * M_LOG2E);
155	    // Set the pointers and strides.
156	    params.q_ptr = q.data_ptr();
157	    params.k_ptr = kcache.data_ptr();
158	    params.o_ptr = out.data_ptr();
159	    params.softmax_lse_ptr = softmax_lse.data_ptr();
160	    // All stride are in elements, not bytes.
161	    params.q_batch_stride = q.stride(0);
162	    params.k_batch_stride = kcache.stride(0);
163	    params.o_batch_stride = out.stride(0);
164	    params.q_row_stride = q.stride(-3);
165	    params.k_row_stride = kcache.stride(-3);
166	    params.o_row_stride = out.stride(-3);
167	    params.q_head_stride = q.stride(-2);
168	    params.k_head_stride = kcache.stride(-2);
169	    params.o_head_stride = out.stride(-2);
170	
171	    params.block_table = block_table.data_ptr<int>();
172	    params.block_table_batch_stride = block_table.stride(0);
173	    params.page_block_size = page_block_size;
174	    
175	    params.tile_scheduler_metadata_ptr = tile_scheduler_metadata.data_ptr<int>();
176	    params.num_sm_parts = tile_scheduler_metadata.size(0);
177	    params.num_splits_ptr = num_splits.data_ptr<int>();
178	
179	    const int total_num_splits = batch_size + params.num_sm_parts;
180	    at::Tensor softmax_lse_accum = torch::empty({total_num_splits, num_heads, q_seq_per_hk}, opts.dtype(at::kFloat));
181	    at::Tensor out_accum = torch::empty({total_num_splits, num_heads, q_seq_per_hk, head_size_v}, opts.dtype(at::kFloat));
182	    CHECK_CONTIGUOUS(softmax_lse_accum);
183	    CHECK_CONTIGUOUS(out_accum);
184	    params.total_num_splits = total_num_splits;
185	    params.softmax_lseaccum_ptr = softmax_lse_accum.data_ptr();
186	    params.oaccum_ptr = out_accum.data_ptr();
187	
188	    auto stream = at::cuda::getCurrentCUDAStream().stream();
189	    // TORCH_CHECK(head_size_k == 576);
190	    if (q_dtype == torch::kBFloat16) {
191	        run_flash_splitkv_mla_kernel<cutlass::bfloat16_t>(params, stream);
192	        run_flash_mla_combine_kernel<cutlass::bfloat16_t>(params, stream);
193	    } else if (q_dtype == torch::kHalf) {
194	#ifdef FLASH_MLA_DISABLE_FP16
195	        TORCH_CHECK(false, "FlashMLA is compiled with -DFLASH_MLA_DISABLE_FP16. Please remove this flag from your environment and re-compile FlashMLA.");
196	#else
197	        run_flash_splitkv_mla_kernel<cutlass::half_t>(params, stream);
198	        run_flash_mla_combine_kernel<cutlass::half_t>(params, stream);
199	#endif
200	    } else {
201	        TORCH_CHECK(false, "Unsupported tensor dtype for query");
202	    }
203	
204	    out = out.view({batch_size, seqlen_q_ori, num_q_heads_per_hk, num_heads_k, head_size_v}).transpose(2, 3)
205	            .reshape({batch_size, seqlen_q_ori, num_heads_q, head_size_v});
206	    softmax_lse = softmax_lse.view({batch_size, num_heads_k, seqlen_q_ori, num_q_heads_per_hk}).transpose(2, 3)
207	            .reshape({batch_size, num_heads_q, seqlen_q_ori});
208	
209	    return {out, softmax_lse};
210	}
211	
212	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
213	    m.doc() = "FlashMLA";
214	    m.def("get_mla_metadata", &get_mla_metadata);
215	    m.def("fwd_kvcache_mla", &mha_fwd_kvcache_mla);
216	}
